pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep amount in a wide admissible domain (positive, practical ether amounts)
        amount = bound(amount, 1, 1e18);

        // fund the test contract so it can pay gas-free accounting; then fund c directly
        vm.deal(address(this), 1e20);
        vm.deal(address(c), amount);

        // owner is the deployer of c, i.e. this test contract
        uint256 ownerBefore = address(this).balance;
        uint256 cBefore = address(c).balance;

        vm.prank(address(this));
        c.withdrawAll();

        // general rule: after a successful owner withdrawAll(), the contract's funds
        // have been transferred out: the owner is strictly richer and c holds nothing.
        // The mutant withdraws nothing, so the owner's balance is unchanged and c keeps its balance.
        assertTrue(address(this).balance > ownerBefore && address(c).balance < cBefore);
    }
}

