pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, type(uint128).max);

        // a fuzzed funder deposits `amount` into c via its payable receive
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        require(okDep, "deposit failed");

        uint256 cBefore = address(c).balance;
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // the owner drains the contract
        vm.prank(owner);
        c.withdrawAll();

        // General rule: withdrawAll always pays the contract's full balance to the
        // owner, so the owner gains exactly cBefore and c is left empty.
        assertTrue(
            owner.balance == ownerBefore + cBefore && address(c).balance == 0,
            "withdrawAll must transfer the entire contract balance to the owner"
        );
    }
}

