pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 n, uint8 k, address spender) public {
        // n deposits of 1 wei each -> depositsCount == n, balance == n
        uint256 count = bound(uint256(n), 2, 100);
        vm.deal(address(this), count);
        for (uint256 i = 0; i < count; i++) {
            (bool okDep,) = address(c).call{value: 1}("");
            require(okDep);
        }

        // owner (this contract) spends k wei out via sendMoney to a plain EOA,
        // leaving balance = count - k, which is < depositsCount == count
        uint256 spend = bound(uint256(k), 1, count - 1);
        address target = address(uint160(uint256(uint160(spender)) | 1));
        if (target == address(c) || target == address(this)) {
            target = address(0xBEEF);
        }
        c.sendMoney(target, spend);

        require(address(c).balance == count - spend);
        require(address(c).balance < c.depositsCount());

        // withdrawAll by owner must succeed on the reference for ALL inputs
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

