pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // allow this contract (the owner of c) to accept ETH transfers
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) < type(uint160).max); // avoid overflow edge with owner addr
        bound(amount, 2, 1e30); // amount must differ from depositsCount (which will be 1)

        // actor deposits `amount` wei into c's receive(); depositsCount becomes 1
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        uint256 cBalBefore = address(c).balance;

        // owner withdraws everything
        vm.prank(address(this));
        c.withdrawAll();

        // RULE: withdrawAll drains the contract's entire balance to the owner
        assertTrue(address(c).balance == 0 && cBalBefore == amount && address(this).balance == amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 2, 1e18);

        // owner is the test contract (deployer of c in setUp)
        address owner = address(this);

        // fund the depositor and deposit `amount` wei into c via receive()
        vm.deal(actor, amount);
        vm.prank(actor);
        c.receiveEth{value: amount}();

        uint256 balBefore = address(c).balance;
        uint256 ownerBefore = owner.balance;
        assertTrue(balBefore == amount, "deposit failed");

        // owner drains via withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // GENERAL RULE: withdrawAll transfers the ENTIRE contract balance to the
        // owner: owner gains exactly balBefore wei and c is left with 0.
        assertTrue(
            address(c).balance == 0 && owner.balance == ownerBefore + balBefore,
            "withdrawAll must drain the full balance"
        );
    }

    // allow this contract to receive the withdrawn ether via transfer
    receive() external payable {}
}

// minimal shim: c's receive() is implicit in C; we route deposits through a
// tiny forwarder so the deposit is a normal external call.
contract DepositForwarder {
    C public target;
    constructor(C _t) { target = _t; }
    function deposit() external payable { address(target).call{value: msg.value}(""); }
}
